function u(t,n="—"){if(!t)return n;const r=new Date(t);return Number.isNaN(r.getTime())?n:r.toLocaleString()}function a(t,n=Date.now()){if(!t)return"—";const r=new Date(t).getTime();if(Number.isNaN(r))return"—";const i=n-r;if(i<0)return u(t);const f=Math.floor(i/1e3);if(f<60)return"刚刚";const e=Math.floor(f/60);if(e<60)return`${e} 分钟前`;const o=Math.floor(e/60);if(o<24)return`${o} 小时前`;const s=Math.floor(o/24);return s<=30?`${s} 天前`:u(t)}export{a,u as f};
